D[1837]={"^Increases the damage of your Corruption and Unstable Affliction by (.-)%%%.\n\n|cFFAAAAAACapstone Bonus: Your Corruption, Shadowflame, Conflagrate, Unstable Affliction and Drain Soul can critically hit%.|r%s*$","Aumenta em {{1}}% o dano de Corrupção e Aflição Instável.\n\n|cFFAAAAAABônus de Ápice: Corrupção, Chama Sombria, Conflagrar, Aflição Instável e Drenar Alma podem causar acertos críticos.|r"}
D[1870]={"^Increase your Frost, Fire and Nature damage done by (.-)%% on targets affected by your Frostbrand%.\n\nYour Frost Shock and Elemental Blast has a (.-)%% chance to freeze the target for (.-)%. when used on targets at or further than 15 yards from you%.%s*$","Aumenta em {{1}}% seu dano de Gelo, Fogo e Natureza contra alvos afetados por Marca Gélida.\n\nChoque de Gelo e Explosão Elemental têm {{2}}% de chance de congelar o alvo durante {{3}} quando usados a 15 m ou mais de distância."}
D[1871]={"^Increase your Frost, Fire and Nature damage done by (.-)%% on targets affected by your Frostbrand%.\n\nYour Frost Shock and Elemental Blast has a (.-)%% chance to freeze the target for (.-)%. when used on targets at or further than 15 yards from you%. This effect can only occur every 10 seconds%.%s*$","Aumenta em {{1}}% seu dano de Gelo, Fogo e Natureza contra alvos afetados por Marca Gélida.\n\nChoque de Gelo e Explosão Elemental têm {{2}}% de chance de congelar o alvo durante {{3}} quando usados a 15 m ou mais de distância. Este efeito só pode ocorrer uma vez a cada 10 s."}
D[2502]={"^Increases the attack rate of your Demon or Undead pet by (.-)%% but drains (.-)%% of its health every (.-) seconds%. Lasts (.-)%.%s*$","Aumenta a velocidade de ataque de seu mascote Demônio ou Morto-vivo em {{1}}%, mas absorve {{2}}% de sua vida a cada {{3}} segundos. Dura {{4}}."}
D[2639]={"^|cFF66DDFFLevel 10 Passive|r\nDamage dealt by |cffffffffCrypt Swarm|r now applies 1 stack of |cffffffffCrypt Plague|r and |cffffffffLichfrost|r applies 2 stacks%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nO dano causado por |cffffffffEnxame da Cripta|r agora aplica 1 acúmulo de |cffffffffPeste da Cripta|r, enquanto |cffffffffGeada do Lich|r aplica 2 acúmulos."}
D[2640]={"^|cFF66DDFFLevel 10 Passive|r\nCasting any spell now has a (.-)%% chance to grant you |cffffffffTundra Warriors|r%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nLançar qualquer feitiço agora tem {{1}}% de chance de conceder |cffffffffGuerreiros da Tundra|r."}
D[2641]={"^|cFF66DDFFLevel 10 Passive|r\nIncreases your maximum |cFFFFFFFFLife Force|r by (.-)%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nAumenta sua |cFFFFFFFFForça Vital|r máxima em {{1}}."}
