D[3377]={"^Increases the range of your Rime spells by (.-) yds and increases the Frost critical strike chance of you and your summons by (.-)%%%.%s*$","Aumenta em {{1}} m o alcance dos seus feitiços de Geada e aumenta em {{2}}% a sua chance e a das suas evocações de causar acertos críticos com Gelo."}
D[3378]={"^While you are below 50%% health, your Undead minions now heal you for (.-)%% of their damage dealt%.%s*$","Enquanto você estiver com menos de 50% de vida, seus lacaios mortos-vivos curam você em {{1}}% do dano que causam."}
D[3610]={"^Each of your summons now reduces your damage taken by (.-)%%, up to a maximum of (.-)%%%.%s*$","Cada uma das suas evocações agora reduz o dano que você recebe em {{1}}%, até um máximo de {{2}}%."}
D[3733]={"^Increases maximum |cffffffffCryptfury|r stacks by (.-)%.%s*$","Aumenta o máximo de |cffffffffFúria da Cripta|r em {{1}}."}
D[3734]={"^Increases |cffffffffLife Force|r by (.-)%.%s*$","Aumenta sua |cffffffffForça Vital|r em {{1}}."}
D[3735]={"^Increases your maximum health and the maximum health of your summons by (.-)%%%.%s*$","Aumenta sua vida máxima e a vida máxima de suas evocações em {{1}}%."}
D[3736]={"^Increases all diseases durations by (.-)%%%s*$","Aumenta as durações de todas as doenças em {{1}}%."}
D[3757]={"^Casting |cff90ee90Command|r spells now has a (.-)%% chance to reset the cooldown of |cffffffffIce Barrage|r and make your cast next within (.-) free of cost%.%s*$","Lançar feitiços de |cff90ee90Comando|r agora tem {{1}}% de chance de reiniciar a recarga de |cffffffffBarragem de Gelo|r e fazer seu próximo uso dentro de {{2}} não ter custo."}
D[3758]={"^Increases the duration |cffffffffUnholy Frenzy|r by (.-) sec and casting |cff90ee90Command|r spells now reduces its cooldown by (.-) sec%.%s*$","Aumenta a duração de |cffffffffFrenesi Profano|r em {{1}} s e lançar |cff90ee90Comando|r agora reduz sua recarga em {{2}} s."}
D[3759]={"^Increases the Armor of your Undead minions by (.-), scaling with your level%.%s*$","Aumenta a armadura de seus lacaios mortos-vivos em {{1}}, escalando com seu nível."}
D[3761]={"^Increases the critical strike chance of |cffffffffFlesh to Worms|r by (.-)%% against enemies below 35%% maximum health%.%s*$","Aumenta a chance de acerto crítico de |cffffffffCarne em Vermes|r em {{1}}% contra inimigos com menos de 35% de vida máxima."}
D[3762]={"^Applying |cffffffffCrypt Plague|r now extends the duration of |cffffffffFlesh to Worms|r on the target by (.-) sec%.%s*$","Aplicar |cffffffffPeste da Cripta|r agora estende em {{1}} s a duração de |cffffffffCarne em Vermes|r no alvo."}
D[3801]={"^Increases your Frost, Fire and Nature damage dealt to targets affected by your Frostbrand Weapon by (.-)%%%.%s*$","Aumenta em {{1}}% o dano de Gelo, Fogo e Natureza causado a alvos afetados por sua |cffffffffArma de Marca Gélida|r."}
