D[3905]={"^Frost Damage dealt has a 60%% chance to apply |cffffffffDeathchill|r, dealing (.-) Frost Damage and stacking (.-) times, for (.-)%.\n\nAt 10 stacks of |cffffffffDeathchill|r, apply |cffffffffIcy Tomb|r to the enemy%.%s*$","O dano de Gelo causado tem 60% de chance de aplicar |cffffffffCalafrio da Morte|r, causando {{1}} de dano de Gelo e acumulando até {{2}} vezes durante {{3}}.\n\nAo atingir 10 acúmulos de |cffffffffCalafrio da Morte|r, aplica |cffffffffTúmulo Gélido|r ao inimigo."}
D[3938]={"^Increases your maximum |cFFFFFFFFLife Force|r by (.-)%.%s*$","Aumenta sua |cFFFFFFFFForça Vital|r máxima em {{1}}."}
D[3945]={"^Impales all enemies within (.-) affected by |cffffffffDeathchill|r for (.-) Frost Damage and consumes a |cffffffffDeathchill|r stack from them%.%s*$","Empala todos os inimigos em um raio de {{1}} afetados por |cffffffffCalafrio da Morte|r, causando {{2}} de dano de Gelo e consumindo 1 acúmulo de |cffffffffCalafrio da Morte|r de cada alvo."}
D[3959]={"^The target becomes blighted, causing nearby enemies to suffer (.-) Shadow damage over (.-)%.\n\nAfter (.-), the blight expunges from the target dealing (.-) Nature damage%.%s*$","O alvo é tomado pela Praga, fazendo inimigos próximos sofrerem {{1}} de dano de Sombra ao longo de {{2}}.\n\nApós {{3}}, a Praga é expurgada do alvo e causa {{4}} de dano de Natureza."}
D[4012]={"^Chill the bones of an enemy and up to (.-) nearby enemies, dealing (.-) Shadowfrost Damage, reduced by (.-)%% per target%.%s*$","Gela os ossos de um inimigo e de até {{1}} inimigos próximos, causando {{2}} de dano de Gelo Sombrio, reduzido em {{3}}% por alvo adicional."}
D[4019]={"^Disease an enemy, dealing (.-) Plague damage and generating Runic Power every (.-) sec for (.-)%.%s*$","Infecta um inimigo, causando {{1}} de dano de Praga e gerando Poder Rúnico a cada {{2}} s durante {{3}}."}
D[4020]={"^Disease an enemy, dealing (.-) Plague damage and generating Runic Power every (.-) sec for (.-)%.\n\nPeriodic damage dealt by this can critically strike%.%s*$","Infecta um inimigo, causando {{1}} de dano de Praga e gerando Poder Rúnico a cada {{2}} s durante {{3}}.\n\nO dano periódico causado por este efeito pode causar acerto crítico."}
D[4021]={"^Throw a plague bomb at the target location, dealing (.-) Plague Damage to up to (.-) enemies%. \n\nEnemies in the area incur a stack of |cffffffffCrypt Plague|r every (.-) sec for (.-)%.%s*$","Arremessa uma |cffffffffBomba de Praga|r no local selecionado, causando {{1}} de dano de Praga até {{2}} inimigos.\n\nOs inimigos na área recebem 1 acúmulo de |cffffffffPeste da Cripta|r a cada {{3}} s durante {{4}}."}
D[4022]={"^Bury an enemy alive with necrotic energy, banishing them, preventing all actions and making them immune to damage for (.-)%.%s*$","Enterra um inimigo vivo com energia necrótica, banindo-o, impedindo todas as ações e deixando-o imune a dano durante {{1}}."}
D[4023]={"^For the next (.-) your diseases mutate causing them to act with accelerated lethality, allowing your freshly applied diseases to tick (.-)%% faster%.%s*$","Durante os próximos {{1}}, suas doenças sofrem mutação e passam a agir com letalidade acelerada, fazendo com que doenças recém-aplicadas causem seus pulsos {{2}}% mais rápido."}
D[4024]={"^Increases the target's damage taken from your Necromancer diseases by (.-)%% for (.-), stacking (.-) times%.%s*$","Aumenta em {{1}}% o dano que o alvo recebe das suas doenças de Necromante durante {{2}}. Acumula até {{3}} vezes."}
D[4091]={"^Create a |cFFFFFFFFPhylactery|r near you for (.-)%.\n\nUpon taking damage which would bring you below 10%% health, become a |cFFFFFFFFShade|r, protecting you from all physical attacks and spells, but during that time you cannot attack or cast spells%.\n\nReaching your |cFFFFFFFFPhylactery|r in this state revives you with (.-)%% of your maximum health%. If you do not reach it in time you will die%.%s*$","Cria um |cFFFFFFFFFilactério|r perto de você durante {{1}}.\n\nAo sofrer dano que reduziria sua vida para menos de 10%, você se transforma em uma |cFFFFFFFFSombra|r, ficando imune a ataques físicos e feitiços, mas sem poder atacar nem lançar feitiços durante esse período.\n\nAlcançar seu |cFFFFFFFFFilactério|r nesse estado revive você com {{2}}% da vida máxima. Se não o alcançar a tempo, você morre."}
D[4116]={"^Channel a swarm of locusts on an enemy, dealing (.-) Shadow damage slowing their movement speed by (.-)%%, and generating Runic Power over (.-)%. \n\nEmpowers nearby active Undead minions with |cffffffffCryptfury|r%.%s*$","Canaliza um enxame de gafanhotos sobre um inimigo, causando {{1}} de dano de Sombra, reduzindo sua velocidade de movimento em {{2}}% e gerando Poder Rúnico ao longo de {{3}}.\n\nFortalece os lacaios mortos-vivos ativos próximos com |cffffffffFúria da Cripta|r."}
D[4117]={"^Channel a swarm of locusts on an enemy, dealing (.-) Shadow damage slowing their movement speed by (.-)%%, and generating Runic Power over (.-)%.%s*$","Canaliza uma nuvem de gafanhotos sobre um inimigo, causando {{1}} de dano de Sombra, reduzindo sua velocidade de movimento em {{2}}% e gerando Poder Rúnico ao longo de {{3}}."}
D[4118]={"^Channel a swarm of locusts on an enemy, dealing (.-) Shadow damage and generating Runic Power over (.-)%. \n\nEmpowers nearby active Undead minions with |cffffffffCryptfury|r%.%s*$","Canaliza um enxame de gafanhotos sobre um inimigo, causando {{1}} de dano de Sombra e gerando Poder Rúnico ao longo de {{2}}.\n\nFortalece os lacaios mortos-vivos ativos próximos com |cffffffffFúria da Cripta|r."}
D[4119]={"^Channel a swarm of locusts on an enemy, dealing (.-) Shadow damage and generating Runic Power over (.-)%.%s*$","Canaliza uma nuvem de gafanhotos sobre um inimigo, causando {{1}} de dano de Sombra e gerando Poder Rúnico ao longo de {{2}}."}
D[4120]={"^Frozen spikes erupt from the bodies of an ally and |cffffffffRaised|r minions for (.-), causing (.-) Frost damage to attackers when hit%.%s*$","Espinhos congelados irrompem do corpo de um aliado e dos lacaios |cffffffffAnimados|r durante {{1}}, causando {{2}} de dano de Gelo aos atacantes quando o alvo é atingido."}
D[4121]={"^Disease an enemy, siphoning (.-) health every (.-) sec for (.-), healing you for a portion of the damage dealt%.\n\nThe plague intensifies and siphons increased health based on how close to death your target is%.%s*$","Aflige um inimigo com uma doença, drenando {{1}} de vida a cada {{2}} s durante {{3}} e curando você por uma parte do dano causado.\n\nA praga se intensifica e drena mais vida quanto mais próximo da morte o alvo estiver."}
D[4122]={"^Raise a |cffffffffSkeletal Rogue|r to aid you in combat, occupying 1 |cffffffffLife Force|r%. \n\nHas a chance to apply |cffffffffDecaying Poison|r on hit, reducing the target's casting speed by (.-)%% for (.-), stacking (.-) times%.\n\n|cff90ee90Command|r: Leaps to your target and strikes it (.-) times%. Always strikes 5 times on enemies below 35%% health%.%s*$","Anima um |cffffffffLadino Esquelético|r para ajudar você em combate, ocupando 1 ponto de |cffffffffForça Vital|r.\n\nSeus golpes têm chance de aplicar |cffffffffVeneno da Decomposição|r, reduzindo em {{1}}% a velocidade de lançamento do alvo durante {{2}}. Acumula até {{3}} vezes.\n\n|cff90ee90Comando|r: salta até o alvo e o golpeia {{4}} vezes. Contra inimigos com menos de 35% de vida, sempre golpeia 5 vezes."}
D[4123]={"^Raise a |cffffffffLesser Skeletal Warrior|r to aid you in combat, occupying 1 |cffffffffLife Force|r%.\n\n|cff90ee90Command|r: Strikes an enemy in front of it and deals Weapon Damage plus (.-)%.%s*$","Anima um |cffffffffGuerreiro Esquelético Menor|r para ajudar você em combate, ocupando 1 ponto de |cffffffffForça Vital|r.\n\n|cff90ee90Comando|r: golpeia um inimigo à sua frente, causando o dano da arma mais {{1}}."}
D[4124]={"^Raise a |cffffffffGhoul|r to aid you in combat occupying 1 |cffffffffLife Force|r%. \n\nIts auto attacks restore (.-) health to you%.\n\n|cff90ee90Command|r: Expels leeching plague that strikes up to (.-) nearby enemies, dealing (.-) Plague damage, and healing you for (.-) for each |cffffffffGhoul|r%.%s*$","Anima um |cffffffffCarniçal|r para ajudar você em combate, ocupando 1 ponto de |cffffffffForça Vital|r.\n\nOs ataques automáticos dele restauram {{1}} de vida a você.\n\n|cff90ee90Comando|r: expele uma praga parasitária que atinge até {{2}} inimigos próximos, causando {{3}} de dano de Praga e curando você em {{4}} para cada |cffffffffCarniçal|r ativo."}
D[4125]={"^Transform into a |cFFFFFFFFLich|r, becoming Undead increasing your Frost damage dealt by (.-)%%%.\n\nWhile active you generate (.-) Runic Power every (.-) sec%.%s*$","Transforma você em um |cFFFFFFFFLich|r, tornando-o Morto-vivo e aumentando em {{1}}% o dano de Gelo causado.\n\nEnquanto a forma estiver ativa, você gera {{2}} de Poder Rúnico a cada {{3}} s."}
D[4126]={"^Transform into a |cFFFFFFFFLich|r, becoming Undead increasing your Frost damage dealt by (.-)%%%.\n\nWhile active you generate (.-) Runic Power every (.-) sec%.\n\nWhile Undead, you are immune to fear, sleep, and charm effects%.%s*$","Transforma você em um |cFFFFFFFFLich|r, tornando-o Morto-vivo e aumentando em {{1}}% o dano de Gelo causado.\n\nEnquanto a forma estiver ativa, você gera {{2}} de Poder Rúnico a cada {{3}} s.\n\nEnquanto for Morto-vivo, você é imune a efeitos de Medo, Sono e Encantamento."}
D[4139]={"^Raise a |cffffffffDecaying Colossus|r to aid you in combat, occupying 3 |cffffffffLife Force|r%. \n\nWhile active, (.-)%% of all damage taken by the caster is taken by the |cffffffffDecaying Colossus|r%.\n\n|cff90ee90Command|r: Unleash a powerful attack dealing Weapon Damage plus (.-) to all enemies in front of it%.%s*$","Anima um |cffffffffColosso em Decomposição|r para ajudar você em combate, ocupando 3 pontos de |cffffffffForça Vital|r.\n\nEnquanto estiver ativo, o |cffffffffColosso em Decomposição|r recebe {{1}}% de todo o dano que seria sofrido pelo conjurador.\n\n|cff90ee90Comando|r: desfere um ataque poderoso contra todos os inimigos à frente, causando o dano da arma mais {{2}}."}
D[4140]={"^Command your |cFFFFFFFFUndead|r to focus their attacks on the target enemy%.\n\nUsable while casting or channeling%.%s*$","Ordena que seus |cFFFFFFFFMorto-vivo|r concentrem os ataques no inimigo selecionado.\n\nPode ser usada enquanto você lança ou canaliza um feitiço."}
