D[5531]={"^Damage dealt by |cffffffffHarvest Plague|r now has a (.-)%% chance to summon a |cFFFFFFFFLesser Zombie|r to aid you in combat for (.-)%.%s*$","O dano causado por |cffffffffPeste da Colheita|r agora tem {{1}}% de chance de evocar um |cFFFFFFFFZumbi Menor|r para ajudar você em combate durante {{2}}."}
