D[5807]={"^Increases the damage of |cffffffffSandblast|r and |cffffffffUnmake|r by (.-)%%%.%s*$","Aumenta o dano de |cffffffffRajada de Areia|r e |cffffffffDesfazer|r em {{1}}%."}
