D[5809]={"^Increases the damage of |cffffffffSandblast|r by (.-)%%%.%s*$","Aumenta em {{1}}% o dano de |cffffffffRajada de Areia|r."}
D[5978]={"^You infect the enemy with (.-) stacks of Crypt |cfffeff9ePlague|r%.\n\nWhen Crypt |cfffeff9ePlague|r expires or the target dies, the host explodes, dealing |cff01cdfePlague Damage|r to them and all other enemies around them%. \n\nSubsequent applications of Crypt |cfffeff9ePlague|r do not refresh its duration%.%s*$","Infecta o inimigo com {{1}} acúmulos de |cfffeff9ePeste da Cripta|r.\n\nQuando |cfffeff9ePeste da Cripta|r expira ou o alvo morre, o hospedeiro explode, causando |cff01cdfeDano de Praga|r a ele e a todos os outros inimigos próximos.\n\nAplicações posteriores de |cfffeff9ePeste da Cripta|r não renovam sua duração."}
D[5994]={"^|cffffffff3 Charges|r\n|cffffffff20 sec recharge|r\nAnimates a |cffffffffRotling|r that leaps to the target and explodes after (.-), dealing (.-) Plague Damage to up to (.-) enemies%.\n\n|cffffffffUnholy Command|r: Leap at target enemy and deal (.-) Plague Damage%.\n\nShares a cooldown with |cffffffffAnimate: Zombie|r%. Usable while moving%.%s*$","|cffffffff3 Cargas|r\n|cffffffff20 s de recarga|r\nAnima um |cffffffffPodrinho|r que salta até o alvo e explode após {{1}}, causando {{2}} de dano de Praga até {{3}} inimigos.\n\n|cffffffffComando Profano|r: salta até o inimigo selecionado e causa {{4}} de dano de Praga.\n\nCompartilha recarga com |cffffffffAnimar: Zumbi|r. Pode ser usado em movimento."}
D[5995]={"^|cffffffff3 Charges|r\n|cffffffff20 sec recharge|r\nAnimates a |cffffffffRotling|r that leaps to the target and explodes after (.-), dealing (.-) Plague Damage to up to (.-) enemies%.\n\nShares a cooldown with |cffffffffAnimate: Zombie|r%. Usable while moving%.%s*$","|cffffffff3 Cargas|r\n|cffffffff20 s de recarga|r\nAnima um |cffffffffPodrinho|r que salta até o alvo e explode após {{1}}, causando {{2}} de dano de Praga até {{3}} inimigos.\n\nCompartilha recarga com |cffffffffAnimar: Zumbi|r. Pode ser usado em movimento."}
D[6132]={"^Transform an enemy into a ghoul, fearing them for (.-) %(9 sec vs%. players%)%. Only usable on Humanoids%. Damage caused may interrupt the effect%.%s*$","Transforma um inimigo em um carniçal, fazendo-o fugir de medo durante {{1}} (9 s contra jogadores). Só pode ser usado em Humanoides. O dano causado pode interromper o efeito."}
D[6133]={"^Transform an enemy into a ghoul, fearing them for (.-) %(8 sec vs%. players%)%. Only usable on Humanoids%. Damage caused may interrupt the effect%.%s*$","Transforma um inimigo em um carniçal, fazendo-o fugir de medo durante {{1}} (8 s contra jogadores). Só pode ser usado em Humanoides. O dano causado pode interromper o efeito."}
D[6370]={"^Channel life into your |cFFFFFFFFRaised|r minions within (.-) yds for (.-), healing them for (.-)%% of their maximum health plus (.-) every (.-) sec%.%s*$","Canaliza vida para seus lacaios |cFFFFFFFFAnimados|r em um raio de {{1}} m durante {{2}}, curando-os em {{3}}% da vida máxima mais {{4}} a cada {{5}} s."}
D[6431]={"^Launch a chain of frost at an enemy, dealing (.-) Frost Damage every (.-) sec for (.-)%.\n\nEach tick generates (.-) Runic Power%.%s*$","Lança uma corrente de gelo contra um inimigo, causando {{1}} de dano de Gelo a cada {{2}} s durante {{3}}.\n\nCada pulso gera {{4}} de Poder Rúnico."}
D[6432]={"^Increases the critical strike chance of |cffffffffIce Barrage|r by (.-)%% against |cff3399ffFrozen|r targets%.%s*$","Aumenta em {{1}}% a chance de acerto crítico de |cffffffffBarragem de Gelo|r contra alvos |cff3399ffCongelado|r."}
D[6433]={"^Every 3rd |cff90ee90Command|r spell now freezes the target in place for (.-)%. Damage dealt may end this effect%.%s*$","A cada terceiro feitiço de |cff90ee90Comando|r, o alvo é congelado no lugar durante {{1}}. O dano recebido pode encerrar o efeito."}
D[6434]={"^|cffffffffChill Touch|r now reduces the target's melee and ranged attack speed by (.-)%% for (.-) sec, stacking (.-) times%.%s*$","|cffffffffToque Gélido|r agora reduz a velocidade de ataque corpo a corpo e à distância do alvo em {{1}}% durante {{2}} s, com até {{3}} acúmulos."}
D[6435]={"^Chill an enemy's heart, interrupting their current spell cast%.\n\nSuccessfully interrupting a spell also reduces their movement speed and haste by (.-)%% for (.-)%.%s*$","Gela o coração de um inimigo e interrompe o feitiço que ele está lançando.\n\nInterromper um feitiço com sucesso também reduz em {{1}}% a velocidade de movimento e a aceleração do alvo durante {{2}}."}
D[6457]={"^Bring a dead ally back to life with (.-) health and (.-) mana%.\n\nCan be used in combat%.%s*$","Devolva a vida a um aliado morto com {{1}} vida e {{2}} mana.\n\nPode ser usada em combate."}
D[6509]={"^Reinvigorate your diseases, refreshing all diseases on the target enemy and copying them, preserving their power and duration%.\n\nYou may use this abilty again within 10 sec to |cFFFFFFFFInfest|r another target, applying the copied diseases%.%s*$","Revigora suas doenças, renova todas as doenças no alvo inimigo e as copia, preservando seu poder e duração.\n\nVocê pode usar esta habilidade novamente dentro de 10 s para |cFFFFFFFFInfestar|r outro alvo, aplicando-lhe as doenças copiadas."}
D[6512]={"^Animate a |cffffffffCrypt Fiend|r to aid you in combat for (.-)%.%s*$","Anima um |cffffffffDemônio da Cripta|r para auxiliar você em combate durante {{1}}."}
D[6513]={"^Fire a |cffffffffLich Bolt|r at an enemy, dealing (.-) Shadow Damage, dealing (.-)%% more damage and applying |cFFFFFFFFCrypt Plague|r for each disease you have active on them%.%s*$","Dispara uma |cffffffffSeta do Lich|r contra um inimigo, causando {{1}} de dano de Sombra, mais {{2}}% de dano adicional, e aplicando |cFFFFFFFFPeste da Cripta|r para cada doença sua ativa no alvo."}
D[6514]={"^Instantly deals (.-) Plague Damage to all enemies within (.-) yds affected by at least 1 Necromancer disease%.%s*$","Causa instantaneamente {{1}} de dano de Praga a todos os inimigos em um raio de {{2}} m afetados por pelo menos uma doença de Necromante."}
D[6515]={"^Increases the damage of |cffffffffPlaguewither|r by (.-)%%%.%s*$","Aumenta o dano de |cffffffffDefinhar Praga|r em {{1}}%."}
D[6586]={"^Siphon life from your undead minions, sacrificing (.-)%% of their health to grant yourself an absorb shield equal to half of the health stolen for (.-)%.\n\nUsable while stunned%.%s*$","Drena a vida dos seus lacaios mortos-vivos, sacrificando {{1}}% da vida deles para conceder a você um escudo de absorção equivalente à metade da vida drenada durante {{2}}.\n\nPode ser usada enquanto estiver atordoado."}
D[6587]={"^Command your active |cffffffffAnimates|r to perform a unique attack%.\n\nUsable while casting or channeling%.%s*$","Ordena que seus lacaios |cffffffffAnimados|r ativos executem um ataque especial.\n\nPode ser usada enquanto você conjura ou canaliza."}
D[6589]={"^Disease an enemy, dealing (.-) Plague Damage every (.-) sec for (.-)%.\n\nAfter (.-), the target explodes, dealing (.-) Plague damage to all enemies within (.-) yards%.%s*$","Infecta um inimigo, causando {{1}} de dano de Peste a cada {{2}} s durante {{3}}.\n\nApós {{4}}, o alvo explode, causando {{5}} de dano de Peste a todos os inimigos em um raio de {{6}} m."}
D[6590]={"^Disease an enemy, dealing (.-) Plague damage every (.-) sec for (.-)%. \n\nDamage increased by (.-)%% for each Necromancer disease on the enemy%.%s*$","Aflige um inimigo com uma doença, causando {{1}} de dano de Praga a cada {{2}} s durante {{3}}.\n\nO dano aumenta em {{4}}% para cada doença de Necromante ativa no inimigo."}
D[6677]={"^Damage dealt by your Undead minions now has a (.-)%% chance to cast |cFFFFFFFFPlague Horde|r on themselves for (.-) and emit |cffffffffZombie Plague|r, dealing (.-) Plague damage to their target%.%s*$","O dano causado pelos seus lacaios mortos-vivos tem {{1}}% de chance de lançar |cFFFFFFFFHorda da Peste|r neles mesmos durante {{2}} e emitir |cffffffffPeste Zumbi|r, causando {{3}} de dano de Praga ao alvo."}
D[6678]={"^Whenever you or a permanent pet you control takes non%-periodic damage, you have a chance to afflict the attacker with your Flesh to Worms |cffff3232Disease|r%. \n\nOnly functions if you know the Flesh to Worms spell%.%s*$","Sempre que você ou uma mascote permanente sob seu controle sofrer dano não periódico, haverá uma chance de afligir o atacante com sua doença |cffff3232Carne em Vermes|r.\n\nSó funciona se você conhecer o feitiço |cffffffffCarne em Vermes|r."}
D[6679]={"^Reduces the cast time of |cffffffffLichfrost|r by (.-)%% and reduces your spell pushback suffered from taking damage by (.-)%%%.%s*$","Reduz em {{1}}% o tempo de lançamento de |cffffffffGeada do Lich|r e em {{2}}% o atraso de lançamento sofrido ao receber dano."}
D[6700]={"^Periodic damage now heals you for (.-)%% of the damage dealt%.%s*$","O dano periódico agora cura você em {{1}}% do dano causado."}
D[6846]={"^Increases the duration of the Rotlings created by your Animate: Rotling spell by (.-)%%%.\n\nIn addition, dealing Periodic Damage to an enemy now has a small chance to summon a Rotling%.%s*$","Aumenta em {{1}}% a duração dos |cffffffffPodrinhos|r criados por |cffffffffAnimar: Podrinho|r.\n\nAlém disso, causar dano periódico a um inimigo tem uma pequena chance de evocar um |cffffffffPodrinho|r."}
D[6884]={"^Allows you to summon Undead minions using |cffffffffLife Force|r%.\n\nSummoned minions gain Attack Power and Spell Power from your Intellect and Spell Power based on their Life Force%.\n\nThey also inherit a portion of your resistances, armor, hit chance, critical strike chance, haste and gain expertise from your hit chance%.%s*$","Permite evocar lacaios mortos-vivos usando |cffffffffForça Vital|r.\n\nOs lacaios evocados recebem Poder de Ataque e Poder Mágico com base no seu Intelecto e Poder Mágico, proporcionalmente à Força Vital que ocupam.\n\nEles também herdam parte das suas resistências, Armadura, chance de acerto, chance de acerto crítico e Aceleração, além de receberem Aptidão com base na sua chance de acerto."}
D[6885]={"^Transform into an undead monstrosity for (.-), increasing your maximum health by (.-)%%%.\n\nWhile transformed you are immune to Fear, Sleep, Charm, and Disease effects%.%s*$","Transforma você em uma monstruosidade morta-viva durante {{1}}, aumentando sua vida máxima em {{2}}%.\n\nEnquanto estiver transformado, você fica imune a Medo, Sono, Encantamento e Doença."}
D[6891]={"^Taunt an enemy to attack you for (.-)%.\n\nIf the target is a player, they are unable to stop moving for (.-)%.%s*$","Provoca um inimigo para atacar você durante {{1}}.\n\nSe o alvo for um jogador, ele não poderá parar de se mover durante {{2}}."}
D[6894]={"^|cffffffffRotlings|r now immediately charge at the target, exploding for (.-)%% increased damage%. Additionally |cffffffffAnimate: Rotling|r is now instant%.%s*$","|cffffffffPodrinhos|r investem imediatamente contra o alvo e explodem, causando {{1}}% a mais de dano. Além disso, |cffffffffAnimar: Podrinho|r passa a ser instantâneo."}
D[6906]={"^Allows Grave March to be castable while casting%.%s*$","Permite lançar Marcha Fúnebre durante outra conjuração."}
D[6940]={"^Hurl putrid necrotic magic at an enemy, dealing (.-) Plague Damage and generating (.-) runic power%.%s*$","Lança magia necrótica pútrida contra um inimigo, causando {{1}} de dano de Praga e gerando {{2}} de Poder Rúnico."}
D[6991]={"^Animate a |cFFFFFFFFSkeletal Smith|r that can repair the equipment of allies for (.-)%.%s*$","Anima um |cFFFFFFFFFerreiro Esquelético|r que pode reparar o equipamento dos aliados durante {{1}}."}
D[7050]={"^Summons a |cffffffffRitual Stone|r at the target location%. You and your allies can interact with the |cffffffffRitual Stone|r to begin channeling their life force into it%. \n\nWhen 10 allies are channeling, the stone will be destroyed to bring forth a hostile |cffffffffFaceless Destroyer|r into the world for (.-)%.%s*$","Evoca uma |cffffffffPedra Ritual|r no local selecionado. Você e seus aliados podem interagir com a |cffffffffPedra Ritual|r para começar a canalizar força vital para ela.\n\nQuando 10 aliados estiverem canalizando, a pedra será destruída para trazer ao mundo um |cffffffffDestruidor sem rosto|r hostil durante {{1}}."}
D[7145]={"^Sacrifices your Undead, returning their |cffffffffLife Force|r to you, and restoring (.-) health for each Undead minion destroyed%.%s*$","Sacrifica seus mortos-vivos, devolvendo a |cffffffffForça Vital|r ocupada por eles e restaurando {{1}} de vida para cada lacaio Morto-vivo destruído."}
D[7146]={"^Enrage your Undead minions for (.-), increasing their haste by (.-)%% and movement speed by (.-)%%%.%s*$","Enfurece seus lacaios mortos-vivos durante {{1}}, aumentando a Aceleração deles em {{2}}% e a velocidade de movimento em {{3}}%."}
D[7149]={"^Increases your maximum |cffffffffLife Force|r by (.-) and increases the casting speed of your |cffffffffRaise|r and |cffffffffAnimate|r spells by (.-)%%%.\n\nAlso gives your Undead minions a (.-)%% chance to generate a |cffffffffFoul Remnant|r%.%s*$","Aumenta sua |cffffffffForça Vital|r máxima em {{1}} e em {{2}}% a velocidade de lançamento dos seus feitiços de |cffffffffAnimar|r.\n\nTambém concede aos seus lacaios mortos-vivos {{3}}% de chance de gerar um |cffffffffResíduo Profano|r."}
D[7150]={"^Teaches you how to raise Flesh Golems and Gurgling Horrors%.%s*$","Ensina você a animar Golems de Carne e Horrores Borbulhantes."}
