D[7184]={"^You channel upon 10 nearby Undead for up to (.-), healing them for (.-)%% of their Maximum Health every (.-) sec%.%s*$","Canaliza sobre até 10 mortos-vivos próximos durante {{1}}, curando-os em {{2}}% da vida máxima a cada {{3}} s."}
D[7268]={"^Increases the duration of |cFFFFFFFFNecrotic Chains|r and |cFFFFFFFFIce Barrage's|r freeze effect by (.-) sec%.%s*$","Aumenta em {{1}} s a duração de |cFFFFFFFFCorrentes Necróticas|r e do efeito de congelamento de |cFFFFFFFFBarragem de Gelo|r."}
D[7269]={"^Tap into necrotic energies, instantly regenerating (.-) Runic Power%.%s*$","Canaliza energias necróticas, regenerando instantaneamente {{1}} de Poder Rúnico."}
D[7287]={"^Reduces the channel and cast time of |cffffffffIce Barrage|r by (.-)%%%.%s*$","Reduz em {{1}}% o tempo de canalização e de lançamento de |cffffffffBarragem de Gelo|r."}
D[7288]={"^Increases your damage against slowed enemies by (.-)%% and increases the duration of |cffffffffHeartchill|r by (.-) sec%.%s*$","Aumenta em {{1}}% seu dano contra inimigos desacelerados e em {{2}} s a duração de |cffffffffCoração Gélido|r."}
D[7289]={"^Casting |cffffffffUnholy Frenzy|r now summons a |cffffffffRotting Frost Giant|r to aid you in combat for the duration%.%s*$","Lançar |cffffffffFrenesi Profano|r agora evoca um |cffffffffGigante Gélido Apodrecido|r para ajudar você em combate enquanto o efeito durar."}
