D[7293]={"^Summon a whirling blizzard, dealing (.-) Frost Damage to (.-) enemies in an (.-) yd radius, and reducing enemy movement speed by (.-)%% while inside%. Lasts (.-)%.%s*$","Evoca uma nevasca giratória, causando {{1}} de dano de Gelo a {{2}} inimigos em um raio de {{3}} m e reduzindo a velocidade de movimento deles em {{4}}% enquanto permanecerem na área. Dura {{5}}."}
D[7365]={"^Casting |cffffffffAnimate|r or |cff90ee90Command|r spells now increases your haste by (.-)%% for (.-), stacking (.-) times%.%s*$","Lançar |cffffffffAnimar|r ou |cff90ee90Comando|r aumenta sua aceleração em {{1}}% durante {{2}}, acumulando-se {{3}} vezes."}
D[7366]={"^Your |cffffffffVirulency|r now applies |cFFFFFFFFRot Fetishist|r for (.-), causing you to replicate 20%% of your periodic damage dealt as direct damage%.%s*$","Sua |cffffffffVirulência|r agora aplica |cFFFFFFFFFetichista da Putrefação|r durante {{1}}, fazendo você replicar como dano direto 20% do dano periódico causado."}
D[7481]={"^Damage dealt by |cffffffffRay of Rot|r and periodic damage has a (.-)%% chance to apply |cffffffffDecaying Presence|r increasing the tick rate of your diseases by (.-)%%, and applies |cffffffffParasites|r for (.-), stacking (.-) times%.\n\n|cffffffffExpunge|r consumes |cffffffffParasites|r to deal (.-)%% increased damage per stack%.%s*$","O dano causado por |cffffffffRaio de Podridão|r e o dano periódico têm {{1}}% de chance de aplicar |cffffffffPresença da Decomposição|r, aumentando em {{2}}% a frequência dos pulsos das suas doenças e aplicando |cffffffffParasitas|r durante {{3}}. Acumula até {{4}} vezes.\n\n|cffffffffExpurgar|r consome |cffffffffParasitas|r para causar {{5}}% a mais de dano por acúmulo."}
D[7483]={"^Adds 2 stacks of Crypt Plague%.%s*$","Adiciona 2 acúmulos de |cffffffffPeste da Cripta|r."}
