D[7501]={"^Applies a dark word to an enemy for (.-), cursing them, and increasing damage they take from your periodic effects by (.-)%%%.%s*$","Aplica uma palavra sombria a um inimigo durante {{1}}, amaldiçoando-o e aumentando em {{2}}% o dano que ele recebe dos seus efeitos periódicos."}
D[7514]={"^Increases spell haste by (.-)%% of your Intellect%.%s*$","Aumenta a aceleração de seus feitiços em {{1}}% de seu Intelecto."}
D[7560]={"^Increases the damage of |cffffffffSand Bomb|r by (.-)%%%.%s*$","Aumenta o dano de |cffffffffBomba de arena|r em {{1}}%."}
D[7600]={"^Increases the range of your Necromancer diseases by (.-) yd and their duration by (.-)%%%.%s*$","Aumenta em {{1}} m o alcance das suas doenças de Necromante e em {{2}}% a duração delas."}
D[7601]={"^Critical strikes now apply a stack of |cffffffffCrypt Plague|r%.%s*$","Agora os acertos críticos aplicam um acúmulo de |cffffffffPeste da Cripta|r."}
