D[56366]={"^You deal (.-)%% increased periodic shadow damage against the target%. Stacks up to (.-) and lasts for (.-)%. Duration cannot be refreshed%.%s*$","Causas um aumento em {{1}}% no dano de Sombra periódico contra o alvo. Acumula até {{2}} e dura em {{3}}. A duração não é possível renovar."}
D[56367]={"^Dealing damage with Drain Soul now applies |cFFFFFFFFRuptured Soul|r%.%s*$","Causar dano com Almasanguínea agora aplica |cFFFFFFFFAlma Rompida|r."}
D[56523]={"^Your next Frostflame Shock is instant, costs no mana, deals (.-)%% increased instant damage and applies |cFFFFFFFFFrostflame Ice Barrage|r%. Lasts for (.-)%.%s*$","Seu próximo Choque de Chama Gélida é instantâneo, não custa mana, causa {{1}}% a mais de dano instantâneo e aplica |cFFFFFFFFBarragem de Gelo e Fogo|r. Dura {{2}}."}
D[56524]={"^Your next Frostflame Shock is instant, costs no mana, deals (.-)%% increased instant damage and applies |cFFFFFFFFFrostflame Ice Barrage|r%. Lasts for (.-)%.\n\nThis buff and Fireball! are consumed at the same time%.%s*$","Seu próximo Choque de Chama Gélida é instantâneo, não custa mana, causa {{1}}% a mais de dano instantâneo e aplica |cFFFFFFFFBarragem de Gelo e Fogo|r. Dura {{2}}.\n\nEste benefício e Bola de Fogo! são consumidos ao mesmo tempo."}
D[56913]={"^Unleash a horrifying wail, stunning 10 nearby enemies and draining (.-) of their life every 1 second for (.-)%.\n\nThis spell cannot miss%.%s*$","Desata um aterrorizante grito, atordoando 10 inimigos próximos e absorvendo você {{1}} de sua vida cada segundo durante {{2}}.\n\nEste feitiço não pode errar."}
