D[76454]={"^Command your |cffffffffCrypt Fiends|r to shoot frost%-congealed webs at your target, dealing (.-) Frost Damage, bouncing to a nearby enemy%. Subsequent instances of this damage deal (.-)%% increased damage to the target for (.-)%.%s*$","Ordena que seus |cffffffffCriaturas dá Cripta|r para que disparem telas congeladas por Gelo em seu alvo, causando {{1}} de dano de Gelo, ricocheteando contra um inimigo próximo. As seguintes instâncias deste dano causam {{2}}% mais dano ao alvo durante {{3}}."}
D[76456]={"^Command your |cffffffffBanshees|r to tear the soul of an enemy apart, draining (.-)%% of the target's mana %(up to a maximum of (.-)%% of their own maximum mana%) and dealing Frost Damage equal to the mana drained%.%s*$","Ordena que suas |cffffffffLâmias|r dilacerem a alma de um inimigo, drenando {{1}}% da mana do alvo, até o máximo de {{2}}% da sua própria mana máxima, e causando dano de Gelo equivalente à mana drenada."}
D[76457]={"^Command your |cffffffffDecaying Colossus|r to charge up a powerful attack over 3 sec that deals Weapon Damage plus (.-) Physical damage to all enemies in a frontal cone%.%s*$","Ordena que seu |cffffffffColosso em Decomposição|r para carregar um ataque poderoso durante 3 s que causa dano da arma mais {{1}} de dano Físico todos os inimigos em um cone frontal."}
D[76458]={"^|cff90ee90Command|r your |cffffffffBanshees|r to tear the soul of an enemy apart, destroying (.-)%% of the target's mana %(up to a maximum of (.-)%% of your own maximum mana%)%.%s*$","|cff90ee90Comando|r seus |cffffffffLamento|r para desgarrar a alma de um inimigo, destruindo {{1}}% da mana do alvo (até um máximo de {{2}}% de sua própria mana máxima)."}
D[76459]={"^Command your |cffffffffAbominations|r to expel an empowered |cffffffffZombie Plague|r, dealing (.-) Plague damage to nearby enemies, generating increased threat%.%s*$","Ordena que seus |cffffffffabominações|r que expulsem uma |cffffffffPeste Zumbi|r, causando {{1}} de dano de Peste aos inimigos próximos, gerando ameaça aumentada."}
D[76461]={"^Raise a |cffffffffGreater Skeletal Warrior|r to aid you in combat, occupying 1 |cffffffffLife Force|r%.\n\n|cff90ee90Command|r: Strikes an enemy in front of it and deals Weapon Damage plus (.-), reducing their Armor by (.-)%% for (.-), stacking (.-) times%.%s*$","Anima um |cffffffffGuerreiro Esquelético Maior|r para ajudar você em combate, ocupando 1 ponto de |cffffffffForça Vital|r.\n\n|cff90ee90Comando|r: golpeia um inimigo à frente, causando o dano da arma mais {{1}} e reduzindo a Armadura do alvo em {{2}}% durante {{3}}. Acumula até {{4}} vezes."}
D[76463]={"^Command your |cffffffffSkeletal Warriors|r to strike up to (.-) enemies in a frontal arc, dealing Weapon Damage plus (.-) Physical Damage and reducing their armor by (.-)%% for (.-), stacking (.-) times%.%s*$","Ordena que seus |cffffffffGuerreiros Esqueléticos|r que atinjam até {{1}} inimigos em um arco frontal, causando dano da arma mais {{2}} de dano Físico e reduz sua armadura em {{3}}% durante {{4}}, acumulando-se {{5}} vezes."}
D[76473]={"^|cff90ee90Command|r your |cffffffffBanshees|r to tear the soul of an enemy apart, |cffff4500Burning|r 10%% of their maximum mana, dealing damage equal to the mana burned%.%s*$","|cff90ee90Comando|r a seus |cffffffffLápidas|r que dilacerem a alma de um inimigo, |cffff4500Ardente|r 10% de sua mana máxima e causando dano equivalente à mana queimado."}
