D[76478]={"^|cff90ee90Command|r your |cffffffffDecaying Colossus|r to charge up a powerful that deals Physical Damage to all enemies in a frontal cone%.%s*$","|cff90ee90Comando|r a seu |cffffffffColosso em Decomposição|r para carregar um poderoso ataque causa dano Físico todos os inimigos dentro de um cone frontal."}
D[76605]={"^|cffffffffBlackjack|r now increases an enemy's chance to be critically struck by you by (.-)%% for (.-)%. \n\nIf the enemy is affected by this when |cffffffffBlackjack|r ends, it applies 1 stack of |cffffffffDeepwood Poison|r%.%s*$","|cffffffffBlackjack|r agora aumenta a chance em {{1}}% de que um inimigo seja atingido criticamente por você durante {{2}}.\n\nSe o inimigo está afetado por isto quando |cffffffffBlackjack|r termina, aplica 1 acúmulo de |cffffffffVeneno da Mata Profunda|r."}
D[76714]={"^|cFF66DDFFLevel 20 Passive|r\nIncreases your spell power by (.-)%% of your Intellect%.%s*$","|cFF66DDFFPassivo de Nível 20|r\nAumenta seu poder mágico em {{1}}% de seu Intelecto."}
D[76719]={"^Each |cffffffffGrave Mage|r now increases the critical strike chance of |cffffffffLichfrost|r and |cffffffffIcequake|r by (.-)%%%.\n\nDamage dealt by |cffffffffGrave Magi|r now increases the damage dealt by your |cffffffffSkeletal Archers'|r next 3 |cfffffffffBlack Arrows|r by (.-)%% for (.-)%.%s*$","Cada |cffffffffMago Sepulcral|r agora aumenta em {{1}}% a chance de acerto crítico de |cffffffffGeada do Lich|r e |cffffffffAbalo Glacial|r.\n\nO dano causado por |cffffffffMagos Sepulcrais|r aumenta em {{2}}% o dano das próximas 3 |cffffffffFlechas Negras|r de seus |cffffffffArqueiros Esqueléticos|r durante {{3}}."}
