D[76786]={"^Increases the critical strike chance of |cffffffffLichfrost|r by (.-)%%%.%s*$","Aumenta em {{1}}% a chance de acerto crítico de |cffffffffGeada do Lich|r."}
D[76787]={"^Increases your Shadow and Frost resistances by 0%.5 per level%.%s*$","Aumenta seus resistências a Sombras e Gelo em 0.5 por nível."}
D[76799]={"^Damage dealt now has a (.-)%% chance to apply |cffffffffParasites|r for (.-)%.%s*$","O dano causado agora tem chance de {{1}}% para aplicar |cffffffffParasitas|r durante {{2}}."}
D[76800]={"^Increases the tick rate of your next Necromancer disease by (.-)%%, stacking 2 times%.%s*$","Aumenta em {{1}}% a frequência dos pulsos da sua próxima doença de Necromante. Acumula até 2 vezes."}
D[76861]={"^Casting spells now has a (.-)%% chance to grant |cffffffffGiant Boneyard|r for 20 sec, stacking 10 times%.\n\nAt 10 stacks, your next spell cast will summon a |cffffffffRotting Frost Giant|r to aid you in combat for 8 sec%.\n\nIn addition, your |cffffffffRotting Frost Giants|r will now also be commanded to deal damage by |cffffffffCommand: Grave Mage|r%.%s*$","Lançar feitiços tem {{1}}% de chance de conceder |cffffffffOssuário Gigante|r durante 20 s. Acumula até 10 vezes.\n\nAo atingir 10 acúmulos, seu próximo feitiço evoca um |cffffffffGigante Gélido Apodrecido|r para ajudar você em combate durante 8 s.\n\nAlém disso, |cffffffffComando: Mago Sepulcral|r também ordena que seus |cffffffffGigantes Gélidos Apodrecidos|r causem dano."}
D[76864]={"^Reduces the cooldown of |cFFFFFFFFSpellblight|r by (.-) sec and causes it to increase the cost of your target's next cast by 50%% for (.-)%.%s*$","Reduz em {{1}} s a recarga de |cFFFFFFFFSpellblight|r e faz a habilidade aumentar em 50% o custo do próximo feitiço lançado pelo alvo durante {{2}}."}
D[76895]={"^Channel to bring forth (.-) |cffffffffRotting Frost Giant|r at target location to aid you in combat for (.-) and generate 20 Runic Power every (.-) sec for (.-)%.\n\nDuring the channel, you may cast |cff90ee90Command|r spells and your Undead minions are guaranteed to critically strike%.%s*$","Canaliza para fazer surgir {{1}} |cffffffffGigante Gélido Apodrecido|r no local selecionado, ajudando você em combate durante {{2}} e gerando 20 de Poder Rúnico a cada {{3}} s durante {{4}}.\n\nDurante a canalização, você pode lançar feitiços de |cff90ee90Comando|r, e seus lacaios mortos-vivos têm acertos críticos garantidos."}
D[76896]={"^Periodic damage dealt now has a (.-)%% chance to apply |cffffffffParasites|r for (.-)%.%s*$","Seu dano periódico agora tem {{1}}% de chance de aplicar |cffffffffParasitas|r durante {{2}}."}
D[76937]={"^Enemies affected by |cffffffffBlight|r become infected, causing the next instance of |cffffffffZombie Plague|r to deal additional Shadow Damage to up to 3 enemies within 5 yds%.%s*$","Inimigos afetados por |cffffffffPraga|r ficam infectados, fazendo com que a próxima ocorrência de |cffffffffPeste Zumbi|r cause dano adicional de Sombra a até 3 inimigos em um raio de 5 m."}
D[77027]={"^|cFF66DDFFLevel 30 Passive|r\nApplying |cFFFFFFFFCrypt Plague|r to an enemy now additionally adds |cffffffffRotting Flesh|r to your Undead minions, increasing their damage dealt by (.-)%% per stack for (.-) sec%.%s*$","|cFF66DDFFPassivo de Nível 30|r\nAplicar |cFFFFFFFFPeste da Cripta|r a um inimigo também concede |cffffffffCarne Apodrecida|r aos seus lacaios mortos-vivos, aumentando em {{1}}% o dano causado por eles por acúmulo durante {{2}} s."}
D[77221]={"^Your |cffffffffLife Force|r is increased by 1%.%s*$","Seu |cffffffffForça Vital|r aumenta em 1."}
D[77231]={"^While |cffffffffLich Form|r is active, damage that reduces you below 35%% of your maximum health now places you in an ice tomb, healing you for (.-)%% of your maximum health and preventing all damage taken for (.-), but making you unable to move or cast spells or abilities%.\n\nCan only occur once every 3 min%.%s*$","Enquanto |cffffffffForma de Lich|r estiver ativa, receber dano que reduziria sua vida para menos de 35% da vida máxima aprisiona você em uma tumba de gelo, curando {{1}}% da sua vida máxima e impedindo todo o dano recebido durante {{2}}, mas impossibilitando movimento e conjuração.\n\nSó pode ocorrer uma vez a cada 3 min."}
D[77232]={"^While |cffffffffLich Form|r is active, damage that reduces you below 35%% of your maximum health now places you in an ice tomb, healing you for (.-)%% of your maximum health and preventing all damage taken for (.-), but making you unable to move or cast spells or abilities%.\n\nCan only occur once every 2 min%.%s*$","Enquanto |cffffffffForma de Lich|r está ativa, o dano que te reduz abaixo de 35% de sua vida máxima agora te coloca em uma tumba de gelo, curando você em {{1}}% de sua vida máxima evitando todo dano recebido durante {{2}}, mas impedindo você de mover nem lançar feitiços ou habilidades.\n\nSó pode ocorrer uma vez a cada 2 min."}
