D[77478]={"^Periodic damage has a (.-)%% chance to make your next |cffffffffPutrefy|r instant%.%s*$","Seu dano periódico tem {{1}}% de chance de fazer com que seu próximo |cffffffffPutrefazer|r seja instantâneo."}
