D[98257]={"^Channel your life force into an ally player for (.-), increasing the effectiveness of active periodic healing spells by (.-)%%%.\n\nEvery (.-) sec, you consume (.-) sec of |cffffffffShadra's Vigil|r from the target to heal them for  (.-) and restore (.-)%% maximum mana%.%s*$","Canaliza sua força vital para um jogador aliado durante {{1}}, aumentando em {{2}}% a eficácia dos efeitos ativos de cura periódica.\n\nA cada {{3}} s, consome {{4}} s de |cffffffffVigília de Shadra|r do alvo para curá-lo em {{5}} e restaurar {{6}}% da mana máxima."}
D[98258]={"^Channel your life force into an ally player for (.-), increasing the effectiveness of active periodic healing spells by (.-)%%%.\n\nEvery (.-) sec, you consume (.-) sec of |cffffffffShadra's Vigil|r from the target to heal them for  (.-)%.%s*$","Canaliza sua força vital para um jogador aliado durante {{1}}, aumentando em {{2}}% a eficácia dos efeitos ativos de cura periódica.\n\nA cada {{3}} s, consome {{4}} s de |cffffffffVigília de Shadra|r do alvo para curá-lo em {{5}}."}
D[98324]={"^Summons a Rotling to aid you in combat for (.-)%.\n\nRotlings do not occupy any Life Force%.%s*$","Invoca um |cffffffffPútrido|r para ajudar você em combate durante {{1}}.\n\nPútridos não ocupam Força Vital."}
D[98374]={"^Reduces the mana cost of |cFFFFFFFFLichfrost|r and |cFFFFFFFFCrypt Swarm|r by (.-)%%%. |cFFFFFFFFBlight|r now refunds 25%% of its base mana cost if it lasts the full duration%.%s*$","Reduz em {{1}}% o custo de mana de |cFFFFFFFFGeada do Lich|r e |cFFFFFFFFEnxame da Cripta|r. |cFFFFFFFFPraga|r agora devolve 25% do custo de mana base caso dure por toda a duração."}
D[98375]={"^Reduces the mana cost of |cFFFFFFFFLichfrost|r and |cFFFFFFFFCrypt Swarm|r by (.-)%%%. |cFFFFFFFFBlight|r now refunds 50%% of its base mana cost if it lasts the full duration%.%s*$","Reduz em {{1}}% o custo de mana de |cFFFFFFFFGeada do Lich|r e |cFFFFFFFFEnxame da Cripta|r. |cFFFFFFFFPraga|r agora devolve 50% do custo básico de mana caso dure por toda a duração."}
D[98397]={"^Raise a |cffffffffBanshee|r to aid you in combat, occupying 2 |cffffffffLife Force|r%.\n\nIt will channel on your target, dealing damage and draining their mana over time%.\n\n|cff90ee90Command|r: Drains (.-)%% of your target's mana %(up to a maximum of (.-)%% of their own maximum mana%) and deals Frost damage equal to the mana drained%.%s*$","Anima uma |cffffffffBanshee|r para ajudar você em combate, ocupando 2 pontos de |cffffffffForça Vital|r.\n\nEla canaliza no alvo, causando dano e drenando mana ao longo do tempo.\n\n|cff90ee90Comando|r: drena {{1}}% da mana do alvo (até o máximo de {{2}}% da mana máxima dele) e causa dano de Gelo igual à mana drenada."}
D[98446]={"^You summon a Skeletal Warrior to assist you in combat%. Consumes 1 Life Force while active%. Life Force is returned to you when this minion dies%.%s*$","Evoca um Guerreiro Esquelético para ajudar você em combate. Consome 1 de Força Vital enquanto estiver ativo. A Força Vital é devolvida quando o lacaio morre."}
D[98447]={"^You summon a Skeletal Warrior to assist you in combat%. Consumes 5 Life Force while active%. Life Force is returned to you when this minion dies%.%s*$","Evoca um Guerreiro Esquelético para ajudar você em combate. Consome 5 de Força Vital enquanto estiver ativo. A Força Vital é devolvida quando o lacaio morre."}
D[98448]={"^You summon a Skeletal Warrior to assist you in combat%. Consumes 2 Life Force while active%. Life Force is returned to you when this minion dies%.%s*$","Evoca um Guerreiro Esquelético para ajudar você em combate. Consome 2 de Força Vital enquanto estiver ativo. A Força Vital é devolvida quando o lacaio morre."}
D[98449]={"^You summon a Skeletal Horror to assist you in combat%. Consumes 5 Life Force while active%. Life Force is returned to you when this minion dies%.%s*$","Evoca um Horror Esquelético para ajudar você em combate. Consome 5 de Força Vital enquanto estiver ativo. A Força Vital é devolvida quando o lacaio morre."}
D[98576]={"^Raise an Abomination to aid you in combat, occupying 3 Life Force%.\n\nIt is surrounded by a disease cloud, dealing (.-) Nature damage to enemies when they deal damage and reducing their attack speed by (.-)%% for (.-)%.\n\nCommand: Instantly unleashes an empowered disease cloud around it%.%s*$","Anima uma Abominação para ajudar você em combate, ocupando 3 pontos de Força Vital.\n\nEla é envolvida por uma nuvem de doenças que causa {{1}} de dano de Natureza aos inimigos quando eles causam dano e reduz em {{2}}% a velocidade de ataque deles durante {{3}}.\n\nComando: libera instantaneamente uma nuvem de doenças fortalecida ao redor dela."}
D[98844]={"^Army%s+of%s+the%s+Dead\n|cffffffffLevel|r%s+|cffff1a1a(.-)|r%s*$","Exército dos Mortos\n|cffffffffNível|r |cffff1a1a{{1}}|r"}
D[102304]={"^The%s+device%s+charges%s+over%s+time%s+using%s+your%s+life%s+force%s+and%s+then%s+directs%s+a%s+burst%s+of%s+energy%s+at%s+your%s+opponent%.%s*$","O dispositivo se carga no tempo usando sua Força de vida e depois dirige uma rajada de energia contra seu oponente."}
D[102318]={"^The%s+life%s+force%s+of%s+the%s+target%s+and%s+caster%s+are%s+linked,%s+sharing%s+damage%s+equally%s+between%s+each%s+other%.%s*$","A força vital do alvo e a do conjurador ficam vinculadas, fazendo com que o dano seja dividido igualmente entre os dois."}
D[102802]={"^You're%s+secretly%s+a%s+necromancer,%s+but%s+you%s+don't%s+know%s+it%.%s+Enemies%s+you%s+slay%s+have%s+a%s+chance%s+to%s+reanimate%.%s*$","Você é secretamente um necromante, mas não sabe disso. Inimigos que você mata têm uma chance de reanimar."}


