T[19220]={"^Increases the cost of |cffffffffIce Barrage|r by (.-), and its damage by (.-)%%%. Lasts (.-)%.\n\nAt 4 or more stacks, |cffffffffIce Barrage|r cleaves up to 3 enemies%.%s*$","Aumenta em {{1}} o custo de |cffffffffBarragem de Gelo|r e em {{2}}% o dano dela. Dura {{3}}.\n\nCom 4 ou mais acúmulos, |cffffffffBarragem de Gelo|r atinge até 3 inimigos."}
T[19268]={"^Affected by a Necromancer Plague%.%s*$","Afetado por uma Praga de Necromante."}
T[19282]={"^Leeching (.-) per 0%.5 sec%.%s*$","Gera uma cura absorvível de {{1}} por 0,5 s."}
T[19329]={"^A Lesser Skeletal Warrior is currently occupying 1 Life Force%.%s*$","Um Guerreiro Esquelético Menor ocupa 1 ponto de Força Vital."}
T[19330]={"^An Abomination is currently occupying 3 Life Force%.%s*$","Uma Abominação ocupa 3 pontos de Força Vital."}
T[19331]={"^A Ghoul is currently occupying 1 Life Force%.%s*$","Um Carniçal ocupa 1 ponto de Força Vital."}
T[19332]={"^A Skeletal Mage is currently occupying 1 Life Force%.%s*$","Um Mago Esquelético ocupa 1 ponto de Força Vital."}
T[19333]={"^A Skeletal Rogue is currently occupying 1 Life Force%.%s*$","Um Ladino Esquelético ocupa 1 ponto de Força Vital."}
T[19334]={"^A Decaying Colossus is currently occupying 3 Life Force%.%s*$","Um Colosso em Decomposição ocupa 3 pontos de Força Vital."}
T[19335]={"^A Skeletal Archer is currently occupying 1 Life Force%.%s*$","Um Arqueiro Esquelético ocupa 1 ponto de Força Vital."}
T[19336]={"^A Gargoyle is currently occupying 3 Life Force%.%s*$","Uma Gárgula ocupa 3 pontos de Força Vital."}
T[19358]={"^Heals the Necromancer for 10%% of all damage dealt%.%s*$","Cura o Necromante em 10% de todo o dano causado."}
T[19398]={"^Redirects 1 harmful spell effect from the Necromancer to his Unholy Champion%.%s*$","Redireciona 1 efeito mágico nocivo do Necromante para o Campeão Profano."}
T[19442]={"^If youre below 20%% health at the end of the duration you will take you will take a large amount of Frost damage%.%s*$","Se está abaixo do 20% de vida quando termina o tempo, receberá um grande dano de Gelo."}
T[19445]={"^A Banshee is currently occupying 2 Life Force%.%s*$","Uma Banshee está ocupando 2 pontos de |cffffffffForça Vital|r."}
T[19446]={"^A Skeletal Warrior is currently occupying 2 Life Force%.%s*$","Um Guerreiro Esquelético ocupa 2 pontos de Força Vital."}
T[19447]={"^A Greater Skeletal Warrior is currently occupying 1 Life Force%.%s*$","Um Guerreiro Esquelético Maior ocupa 1 ponto de Força Vital."}
T[19978]={"^Gehennas is draining your life force causing (.-) Fire damage every (.-) seconds%.%s*$","Gehennas está drenando sua Força vital causando {{1}} de dano de Fogo a cada {{2}} segundos."}
T[20021]={"^Absorbing the life force of the four conduits, Sulfuron Harbinger surrounds himself in Devastating Flames%.%s*$","Ao absorver a força vital dos quatro condutos, Arauto de Sulfuron se envolve em Chamas Devastadoras."}
T[20104]={"^Touch of Death%s*$","Toque de Morte."}
T[20372]={"^Taking (.-)%% more damage from Drain Life%.%s*$","Recebe {{1}}% a mais de dano de Drenar Vida."}
T[20373]={"^Afflicted Soul SLS%s*$","Alma Afligida SLS."}
T[21132]={"^Taking (.-)%% more damage from the casters Drain Life, and (.-)%% more damage from Blood Arrow%.%s*$","Recebe um dano adicional do conjurador de Almasanguíneo em {{1}}%, e um dano adicional do Projétil Sinistro de {{2}}%."}
T[21355]={"^Empowered by the Titans%.\n\n%- Frostbite: Frost spells and abilities chills targets, reducing their movement speed%. Reaching 10 stacks makes the target chilled,and becomes stunned%. Keeping close to allies reduces the stacks of Frostbite!\n\n%- Chains of Ice: The champion forms an Icy chains arounds a player, locking the target in place%.\n\n%- Ice Barrage: Bombards a target player and its nearby allies with icicles%. Each icicle inflicts Frost damage%.\n\n%- Frozen Orb: The Champion lets out a Frozen Orb that moves around pulsating dealing Frost Damage and shoots out frostbolts in random directions dealing Frost Damage%.\n\n%- Absolute Zero: The Frost Champion absorbs all heat and rapidly reduces the temperature dealing Frost damage to everyone%.%s*$","Fortalecido pelos Titãs.\n\n- Mordida Gélida: feitiços e habilidades de Gelo resfriam os alvos e reduzem sua velocidade de movimento. Ao alcançar 10 acúmulos, o alvo congela e fica atordoado. Permanecer perto de aliados reduz os acúmulos!\n\n- Correntes de Gelo: o campeão forma correntes de gelo ao redor de um jogador, imobilizando-o.\n\n- Barragem de Gelo: bombardeia um jogador e os aliados próximos com estilhaços de gelo. Cada estilhaço causa dano de Gelo.\n\n- Orbe Congelado: o campeão lança um orbe congelado que se move, pulsa e causa dano de Gelo, além de disparar setas de gelo em direções aleatórias.\n\n- Zero Absoluto: o campeão absorve todo o calor e reduz rapidamente a temperatura, causando dano de Gelo a todos."}
